def fmt_time(minutes):
    """Format minutes since midnight as zero‑padded HH:MM."""
    h = minutes // 60
    m = minutes % 60
    return f"{h:02d}:{m:02d}"

def interval_intersection(a, b):
    """Return intersection of two interval lists (each a list of (start, end))."""
    i, j = 0, 0
    res = []
    while i < len(a) and j < len(b):
        s = max(a[i][0], b[j][0])
        e = min(a[i][1], b[j][1])
        if s < e:
            res.append((s, e))
        if a[i][1] < b[j][1]:
            i += 1
        else:
            j += 1
    return res

def subtract_intervals(base, removals):
    """Subtract a list of removal intervals from a base interval list."""
    result = []
    for b_start, b_end in base:
        cur_start = b_start
        for r_start, r_end in removals:
            if r_end <= cur_start or r_start >= b_end:
                continue  # no overlap
            if r_start > cur_start:
                result.append((cur_start, r_start))
            cur_start = max(cur_start, r_end)
            if cur_start >= b_end:
                break
        if cur_start < b_end:
            result.append((cur_start, b_end))
    return result

