    m = m % 60
    return f"{h:02d}:{m:02d}"

def merge_intervals(intervals):
    """Merge overlapping or adjacent intervals. Intervals are (start, end) in minutes."""
    if not intervals:
        return []
    intervals.sort()
    merged = [intervals[0]]
    for s, e in intervals[1:]:
        last_s, last_e = merged[-1]
        if s <= last_e:          # overlap or touch
            merged[-1] = (last_s, max(last_e, e))
        else:
            merged.append((s, e))
    return merged

def invert_intervals(busy, outer):
    """Given busy intervals inside outer (start, end), return free intervals."""
    free = []
    cur = outer[0]
    for s, e in busy:
        if cur < s:
            free.append((cur, s))
        cur = max(cur, e)
    if cur < outer[1]:
        free.append((cur, outer[1]))
    return free

def intersect_two(a, b):
    """Intersect two lists of intervals."""
    i, j = 0, 0
    res = []
    while i < len(a) and j < len(b):
        s = max(a[i][0], b[j][0])
        e = min(a[i][1], b[j][1])
        if s < e:
            res.append((s, e))
        if a[i][1] < b[j][1]:
            i += 1
        else:
            j += 1
    return res

